	{{"turnin", 6124, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, {"accept", 6125, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, {"note", "Fly to Rut'theran Village"}, note = "Cast Teleport: Moonglade and see Dendrite Starblaze, then fly to Rut'theran Village and take the portal up to Darnassus.", only = {races = {"NightElf"}}, title = "Curing the Sick"},
	{{"turnin", 6125, at = {1457, 35.37, 8.4}, who = "Mathrengyl Bearwalker"}, only = {races = {"NightElf"}}, title = "Power over Poison"},
	{{"level", 14}, {"accept", 6126, at = {1456, 76.48, 27.22}, who = "Turak Runetotem"}, note = "Turak Runetotem stands on Elder Rise.", only = {races = {"Tauren"}}, title = "Lessons Anew"},
	{{"turnin", 6126, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, {"accept", 6127, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, {"note", "Fly to Thunder Bluff"}, note = "Cast Teleport: Moonglade. Dendrite Starblaze is in Nighthaven. Bunthen Plainswind flies druids to Thunder Bluff; fly on to the Crossroads from there.", only = {races = {"Tauren"}}, title = "Dendrite Starblaze"},
	{{"note", "Fly to Crossroads"}, {"complete", 6127, at = {1413, 48.4, 18.89}}, note = "From the Crossroads head north to Dreadmist Peak and fill the Empty Dreadmist Peak Sampler at the Dreadmist Peak Pool.", only = {races = {"Tauren"}}, title = "Dreadmist Peak"},
	{{"turnin", 6127, at = {1413, 52.26, 31.93}, who = "Tonga Runetotem"}, {"accept", 6128, at = {1413, 52.26, 31.93}, who = "Tonga Runetotem"}, {"have", 2449, 5, at = {1413, 51.39, 30.2}, name = "Earthroot", optional = true}, note = "Tonga Runetotem stands in the Crossroads. No Herbalism? Hula'mahi, a few steps away, sells Earthroot, three at a time until he restocks.", only = {races = {"Tauren"}}, title = "Tonga Runetotem"},
	{{"complete", 6128, at = {1413, 54.82, 40.13}}, note = "Lost Barrens Kodos roam the plains north and west of the Crossroads and around the Stagnant Oasis; each drops a horn. Herbalists find Earthroot all over the northern Barrens.", only = {races = {"Tauren"}}, title = "Earthroot and Kodo Horns"},
	{{"turnin", 6128, at = {1413, 52.26, 31.93}, who = "Tonga Runetotem"}, {"accept", 6129, at = {1413, 52.26, 31.93}, who = "Tonga Runetotem"}, only = {races = {"Tauren"}}, title = "Tonga Runetotem"},
	{{"complete", 6129, at = {1413, 54.5, 32.09}}, note = "Use the Curative Animal Salve on Sickly Gazelles: they graze north of the road that runs east and west through the Crossroads.", only = {races = {"Tauren"}}, title = "Sickly Gazelles"},
	{{"turnin", 6129, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, {"accept", 6130, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, {"note", "Fly to Thunder Bluff"}, note = "Cast Teleport: Moonglade and see Dendrite Starblaze, then take Bunthen Plainswind's flight to Thunder Bluff.", only = {races = {"Tauren"}}, title = "Curing the Sick"},
	{{"turnin", 6130, at = {1456, 76.48, 27.22}, who = "Turak Runetotem"}, only = {races = {"Tauren"}}, title = "Power over Poison"},
