Pathwise.RegisterRoute({category = "Class", classes = {"HUNTER"}, id = "forever/class/hunter/rhokdelar", levels = {60, 60}, map = 1448, title = "Rhok'delar and Lok'delar", steps = {
	{{"accept", 7632}, note = "The Cache of the Firelord appears in Molten Core when Majordomo Executus yields; it holds the Ancient Petrified Leaf about half the time. Molten Core is a 40-player raid inside Blackrock Mountain. Right-click the leaf to start the quest.", title = "The Ancient Petrified Leaf"},
	{{"turnin", 7632, at = {1448, 47.78, 24.08}, who = "Vartrus the Ancient"}, {"accept", 7633, at = {1448, 47.78, 24.08}, who = "Vartrus the Ancient"}, {"turnin", 7633, at = {1448, 47.78, 24.08}, who = "Vartrus the Ancient"}, {"accept", 7636, at = {1448, 47.78, 24.08}, who = "Vartrus the Ancient"}, {"accept", 7635, at = {1448, 48.39, 22.29}, who = "Stoma the Ancient"}, {"accept", 7634, at = {1448, 46.7, 24.06}, who = "Hastat the Ancient"}, note = "Vartrus, Stoma and Hastat the Ancient stand together in the north of Felwood. Alliance: Talonbranch Glade is the nearest flight point; Horde: Bloodvenom Post.", title = "Vartrus the Ancient"},
	{{"goto", 1452, 60.31, 13.18, "Talk to Artorius the Amiable"}, {"complete", 7636, at = {1452, 60.31, 13.18}}, note = "Artorius the Amiable, a tauren, waits in the north-east of Winterspring. Talk to him and he becomes Artorius the Doombringer. Fight every demon alone and without your pet: help of any kind makes it vanish. Loot the head.", title = "Artorius the Doombringer"},
	{{"goto", 1449, 34.32, 40.79, "Talk to Simone the Inconspicuous"}, {"complete", 7636, at = {1449, 34.32, 40.79}}, note = "Simone the Inconspicuous, a troll, stands in the west of Un'Goro Crater. Talk to her and she becomes Simone the Seductress, with a pet of her own. Alone, without your pet.", title = "Simone the Seductress"},
	{{"goto", 1451, 24.72, 76.02, "Talk to Nelson the Nice"}, {"complete", 7636, at = {1451, 24.72, 76.02}}, note = "Nelson the Nice, a gnome, stands in the south-west of Silithus. Talk to him and he becomes Solenor the Slayer. Alone, without your pet; keep away from the beetles he calls.", title = "Solenor the Slayer"},
	{{"goto", 1428, 24.82, 65.93, "Talk to Franklin the Friendly"}, {"complete", 7636, at = {1428, 24.82, 65.93}}, note = "Franklin the Friendly, a human, stands in the west of the Burning Steppes. Talk to him and he becomes Klinfran the Crazed. Alone, without your pet.", title = "Klinfran the Crazed"},
	{{"complete", 7635, at = {1445, 52.1, 75.8}}, note = "Onyxia drops the Mature Black Dragon Sinew; she is the 40-player raid boss of Onyxia's Lair, a cave in the Wyrmbog of southern Dustwallow Marsh.", title = "Onyxia"},
	{{"turnin", 7636, at = {1448, 47.78, 24.08}, who = "Vartrus the Ancient"}, {"turnin", 7635, at = {1448, 48.39, 22.29}, who = "Stoma the Ancient"}, title = "Back to the Ancients"},
	{{"note", "Use Ancient Rune Etched Stave"}, {"goto", 1448, 47.78, 24.08, "Talk to Vartrus the Ancient", optional = true}, note = "Not confirmed in Forever. In Classic, using the Ancient Rune Etched Stave with the Enchanted Black Dragon Sinew in your bags made Rhok'delar, and Vartrus then gave Lok'delar, Stave of the Ancient Keepers (Icy Veins).", title = "Rhok'delar and Lok'delar"},
	{{"complete", 7634, at = {1447, 53.3, 80.4}}, note = "Hastat's quiver needs the Mature Blue Dragon Sinew. Azuregos, a world boss for a raid, roams the south of Azshara and drops it most of the time; the Cobalt dragonkin of Winterspring drop it very rarely. Skip the rest of this guide if you do not want the quiver.", title = "Azuregos"},
	{{"turnin", 7634, at = {1448, 46.7, 24.06}, who = "Hastat the Ancient"}, title = "Hastat the Ancient"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"HUNTER"}, id = "forever/class/hunter/the-hunters-charm", levels = {50, 52}, map = 1447, title = "The Hunter's Charm", steps = {
	{{"level", 50}, {"accept", 8151, at = {1453, 67.59, 35.78}, who = "Ulfir Ironbeard"}, note = "At 50 any Alliance hunter trainer offers it: Ulfir Ironbeard in Stormwind's Dwarven District, Olmin Burningbeard in Ironforge's Hall of Arms or Dorion in Darnassus' Cenarion Enclave.", only = {factions = {"Alliance"}}, title = "The Hunter's Charm (Alliance)"},
	{{"level", 50}, {"accept", 8151, at = {1454, 66.05, 18.53}, who = "Ormak Grimshot"}, note = "At 50 any Horde hunter trainer offers it: Ormak Grimshot in Orgrimmar's Valley of Honor or Holt Thunderhorn on Hunter Rise in Thunder Bluff.", only = {factions = {"Horde"}}, title = "The Hunter's Charm (Horde)"},
	{{"goto", 1447, 11.9, 77.59, "Get the flight path at Talrendis Point", only = {factions = {"Alliance"}}}, {"goto", 1447, 21.96, 49.62, "Get the flight path at Valormok", only = {factions = {"Horde"}}}, {"turnin", 8151, at = {1447, 42.4, 42.62}, who = "Ogtinc"}, {"accept", 8153, at = {1447, 42.4, 42.62}, who = "Ogtinc"}, note = "Ogtinc lives atop the cliffs north-east of the Ruins of Eldarath. Alliance: fly to Talrendis Point; Horde: fly to Valormok.", title = "Ogtinc"},
	{{"complete", 8153, at = {1447, 52.1, 35.39}}, note = "Mosshoof Coursers graze all over Azshara; one in a dozen or so drops a pair of Perfect Courser Antlers.", title = "Courser Antlers"},
	{{"turnin", 8153, at = {1447, 42.4, 42.62}, who = "Ogtinc"}, {"accept", 8231, at = {1447, 42.4, 42.62}, who = "Ogtinc"}, title = "Ogtinc"},
	{{"complete", 8231, at = {1447, 84.6, 30.9}}, note = "Wavethrashers crawl along Azshara's coasts: Young Wavethrashers on the north-east shore and Wavethrashers on the east coast drop the scales about twice as often as the Great Wavethrashers of the south shore.", title = "Wavethrashing"},
	{{"turnin", 8231, at = {1447, 42.4, 42.62}, who = "Ogtinc"}, {"accept", 8232, at = {1447, 42.4, 42.62}, who = "Ogtinc"}, title = "Ogtinc"},
	{{"complete", 8232, at = {1435, 69, 54}}, note = "Morphaz is an elite dragon boss inside the Sunken Temple, a five-player dungeon: bring a group. The temple stands in the middle of the Pool of Tears; swim down into it to reach the entrance. Horde: fly to Stonard; Alliance: fly to Darkshire or Nethergarde Keep and ride on.", title = "Morphaz in the Sunken Temple"},
	{{"turnin", 8232, at = {1447, 42.4, 42.62}, who = "Ogtinc"}, title = "The Green Drake"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"MAGE"}, id = "forever/class/mage/arcane-refreshment", levels = {60, 60}, map = 1444, title = "Conjure Water (Arcane Refreshment)", steps = {
	{{"level", 60}, {"accept", 7463, at = {1444, 58, 44.5}, who = "Lorekeeper Lydros"}, note = "Fly to Feathermoon (Alliance) or Camp Mojache (Horde) and ride to Dire Maul in central Feralas. Lorekeeper Lydros waits in the Athenaeum, the library, reached through the West wing (or the North wing with a Crescent Key).", title = "Lorekeeper Lydros"},
	{{"complete", 7463, at = {1444, 58, 44.5}}, note = "Hydrospawn, a water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool.", title = "Hydrospawn"},
	{{"turnin", 7463, at = {1444, 58, 44.5}, who = "Lorekeeper Lydros"}, title = "Back to Lydros"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"MAGE"}, faction = "Alliance", id = "forever/class/mage/astral-knot-garment", levels = {26, 30}, map = 1453, races = {"Human", "Gnome"}, title = "Astral Knot Garment", steps = {
	{{"level", 26}, {"accept", 1939, at = {1455, 27.25, 8.3}, who = "Bink"}, note = "Bink teaches mages in Ironforge's Mystic Ward. Take the Deeprun Tram from Tinker Town to Stormwind afterwards.", only = {races = {"Gnome"}}, title = "Bink (Ironforge)"},
	{{"level", 26}, {"accept", 1939, at = {1453, 49.56, 85.8}, who = "Jennea Cannon"}, note = "Jennea Cannon stands in the Wizard's Sanctum, the tower of the Mage Quarter.", only = {races = {"Human"}}, title = "Jennea Cannon (Stormwind)"},
	{{"turnin", 1939, at = {1453, 48.71, 87.62}, who = "High Sorcerer Andromath"}, {"accept", 1938, at = {1453, 48.71, 87.62}, who = "High Sorcerer Andromath"}, note = "High Sorcerer Andromath is in the Wizard's Sanctum too.", title = "High Sorcerer Andromath"},
	{{"complete", 1938, at = {1433, 73.77, 47.61}}, note = "Head east through Elwynn Forest into Redridge. The fallen mage's tower of Ilgalar stands in the east of the zone; the treatise is in his library.", title = "The Tower of Ilgalar"},
	{{"turnin", 1938, at = {1453, 48.71, 87.62}, who = "High Sorcerer Andromath"}, {"accept", 1940, at = {1453, 48.71, 87.62}, who = "High Sorcerer Andromath"}, title = "Back to Andromath"},
	{{"complete", 1940, at = {1431, 19.99, 41.24}}, note = "Carrion Recluses lurk in the woods of western Duskwood and each one drops the silk. The Black Widow Hatchlings further east drop it now and then.", title = "Carrion Recluses"},
	{{"turnin", 1940, at = {1453, 51.84, 83.51}, who = "Wynne Larson"}, {"accept", 1942, at = {1453, 51.84, 83.51}, who = "Wynne Larson"}, {"turnin", 1942, at = {1453, 51.84, 83.51}, who = "Wynne Larson"}, note = "Wynne Larson works at Larson Clothiers in the Mage Quarter.", title = "Wynne Larson"},
} })

