	{{"level", 35}, {"accept", 1953, at = {1454, 38.45, 86.13}, who = "Deino"}, note = "Deino, one of Orgrimmar's mage trainers, sends you back to Tabetha; Anastasia Hartwell in the Undercity and Ursyn Ghull in Thunder Bluff give the same quest.", only = {factions = {"Horde"}}, title = "Return to the Marsh (Orgrimmar)"},
	{{"turnin", 1953, at = {1445, 46.06, 57.09}, who = "Tabetha"}, {"accept", 1954, at = {1445, 46.06, 57.09}, who = "Tabetha"}, note = "Tabetha's cottage is deep in the marsh west of Theramore, just north of the Stonemaul Ruins.", title = "Tabetha"},
	{{"complete", 1954, at = {1443, 66.49, 77.94}}, note = "The Burning Blade Summoners work the Mannoroc Coven in southern Desolace; any of them carries an Infernal Orb.", title = "The Infernal Orb"},
	{{"turnin", 1954, at = {1445, 46.06, 57.09}, who = "Tabetha"}, {"accept", 1955, at = {1445, 46.06, 57.09}, who = "Tabetha"}, {"complete", 1955, at = {1445, 45.79, 56.97}}, {"turnin", 1955, at = {1445, 46.06, 57.09}, who = "Tabetha"}, {"accept", 1956, at = {1445, 46.06, 57.09}, who = "Tabetha"}, note = "Tabetha draws the demon out of the orb beside her cottage. The Demon of the Orb is elite: grouping up is advised. You have three minutes before it slips back into the orb.", title = "The Exorcism"},
	{{"complete", 1956, at = {1418, 49.1, 13.7}}, note = "Uldaman is a dungeon in the northern Badlands, by the Meeting Stone: a group of five. Defeat the Obsidian Sentinel inside for its power source.", title = "Power in Uldaman"},
	{{"turnin", 1956, at = {1445, 46.06, 57.09}, who = "Tabetha"}, {"accept", 1957, at = {1445, 46.06, 57.09}, who = "Tabetha"}, {"complete", 1957, at = {1445, 45.83, 56.94}}, {"turnin", 1957, at = {1445, 46.06, 57.09}, who = "Tabetha"}, {"accept", 1958, at = {1445, 46.06, 57.09}, who = "Tabetha"}, {"turnin", 1958, at = {1445, 46.06, 57.09}, who = "Tabetha"}, note = "Back to Tabetha. She opens a mana rift beside her cottage: kill twelve Mana Surges within ten minutes.", title = "Mana Surges"},
