	{{"level", 50}, {"accept", 8250, at = {1454, 39.16, 86.27}, who = "Uthel'nay"}, note = "Uthel'nay, one of Orgrimmar's mage trainers, gives it; so do Pierce Shackleton in the Undercity and Archmage Shymm in Thunder Bluff.", only = {factions = {"Horde"}}, title = "Magecraft (Orgrimmar)"},
	{{"turnin", 8250, at = {1447, 28.11, 50.09}, who = "Sanath Lim-yo"}, {"accept", 8251, at = {1447, 29.25, 40.21}, who = "Archmage Xylem"}, note = "Fly to Talrendis Point (Alliance) or Valormok (Horde). Sanath Lim-yo camps below his master's tower: from the fork of Azshara's main road at the Ruins of Eldarath, head straight north to the cliffs. He teleports you up to Archmage Xylem.", title = "Sanath Lim-yo"},
	{{"complete", 8251, at = {1447, 55.46, 29.5}}, note = "The blood elves camp along the cliffs of north-eastern Azshara; Blood Elf Surveyors and Reclaimers drop the dust.", title = "Glittering Dust"},
	{{"turnin", 8251, at = {1447, 29.25, 40.21}, who = "Archmage Xylem"}, {"accept", 8252, at = {1447, 29.25, 40.21}, who = "Archmage Xylem"}, note = "Back to Sanath Lim-yo, who teleports you up to the tower.", title = "Archmage Xylem"},
	{{"complete", 8252, at = {1447, 36.33, 48.02}}, note = "The Spitelash Sirens walk the ruins and beaches around the Ruins of Eldarath and the bay; they carry the coral.", title = "Enchanted Coral"},
	{{"turnin", 8252, at = {1447, 29.25, 40.21}, who = "Archmage Xylem"}, {"accept", 8253, at = {1447, 29.25, 40.21}, who = "Archmage Xylem"}, note = "Back to Sanath Lim-yo and up to the tower.", title = "Archmage Xylem again"},
	{{"complete", 8253, at = {1435, 69.9, 53.6}}, note = "Morphaz, a green drake, waits deep in the Temple of Atal'Hakkar, the Sunken Temple in the Pool of Tears: a group of five, level 50-54. Kill him for the Arcane Shard.", title = "Morphaz"},
	{{"turnin", 8253, at = {1447, 29.25, 40.21}, who = "Archmage Xylem"}, note = "Back to Azshara, Sanath Lim-yo and the tower.", title = "The Arcane Shard"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"MAGE"}, faction = "Horde", id = "forever/class/mage/ju-ju-heaps", levels = {10, 12}, map = 1411, title = "Ju-Ju Heaps", steps = {
