	{{"complete", 1884, at = {1411, 67.38, 82.5}}, note = "Wade across to the Echo Isles, south-east of Sen'jin. Zalazane placed the heaps among his huts on the main isle: click a heap to destroy it.", title = "The Ju-Ju Heaps"},
	{{"turnin", 1884, at = {1411, 56.31, 75.11}, who = "Un'Thuwa"}, title = "Back to Un'thuwa"},
