	{{"level", 30}, {"accept", 1947, at = {1454, 38.45, 86.13}, who = "Deino"}, note = "Deino, one of Orgrimmar's mage trainers, sends you to Tabetha; Anastasia Hartwell in the Undercity and Ursyn Ghull in Thunder Bluff give the same quest.", only = {factions = {"Horde"}}, title = "Journey to the Marsh (Orgrimmar)"},
	{{"turnin", 1947, at = {1445, 46.06, 57.09}, who = "Tabetha"}, {"accept", 1949, at = {1445, 46.06, 57.09}, who = "Tabetha"}, note = "Tabetha, a hermit, lives in a cottage deep in the marsh west of Theramore, just north of the Stonemaul Ruins.", title = "Tabetha"},
	{{"turnin", 1949, at = {1441, 78.29, 75.7}, who = "Magus Tirth"}, {"accept", 1950, at = {1441, 78.29, 75.7}, who = "Magus Tirth"}, note = "Magus Tirth spends his days at the race track in the Shimmering Flats, south-east Thousand Needles.", title = "Magus Tirth"},
	{{"complete", 1950, at = {1441, 79.6, 75.6}}, {"turnin", 1950, at = {1441, 78.29, 75.7}, who = "Magus Tirth"}, {"accept", 1951, at = {1441, 78.29, 75.7}, who = "Magus Tirth"}, note = "Tirth's apprentice is \"Plucky\" Johnson, a small grey chicken by the race track. Target him and type /beckon: he turns human for a moment, long enough to talk to him.", title = "\"Plucky\" Johnson"},
	{{"complete", 1951, at = {1420, 82.6, 33.8}}, note = "Tirth sold the book to the Scarlet Brotherhood. The Scarlet Monastery stands in north-eastern Tirisfal Glades; take the Library wing. The book juts out of the wall on the left as you enter the Athenaeum, before Arcanist Doan.", title = "Rituals of Power"},
