	{{"level", 15}, {"accept", 1919, at = {1455, 27.16, 8.57}, who = "Dink"}, note = "Dink teaches mages in Ironforge's Mystic Ward. Take the Deeprun Tram from Tinker Town to Stormwind afterwards.", only = {races = {"Gnome"}}, title = "Dink (Ironforge)"},
	{{"turnin", 1919, at = {1453, 49.56, 85.8}, who = "Jennea Cannon"}, {"accept", 1920, at = {1453, 49.56, 85.8}, who = "Jennea Cannon"}, {"complete", 1920, at = {1453, 49.45, 85.48}}, note = "Jennea Cannon stands in the Wizard's Sanctum, the tower of the Mage Quarter. The Chest of Containment Coffers and the Cantation of Manifestation lie behind her.", title = "Jennea Cannon"},
	{{"note", "Use Cantation of Manifestation", optional = true}, {"note", "Kill Rift Spawn", optional = true}, {"complete", 1920, at = {1453, 51.3, 93.3}}, note = "The Blue Recluse is the tavern in the Mage Quarter. Use the Cantation of Manifestation inside to make the Rift Spawn visible, subdue one with your spells, then use the Chest of Containment Coffers to throw down a coffer and capture it.", title = "The Blue Recluse"},
	{{"turnin", 1920, at = {1453, 49.56, 85.8}, who = "Jennea Cannon"}, {"accept", 1921, at = {1453, 49.56, 85.8}, who = "Jennea Cannon"}, title = "Back to Jennea Cannon"},
	{{"complete", 1921, at = {1453, 49.77, 85.79}}, note = "Humanoids drop Linen Cloth; the Auction House in the Trade District sells it.", title = "Linen Cloth"},
	{{"complete", 1921, at = {1432, 35.49, 24.3}}, note = "Take the Deeprun Tram to Ironforge, then the road east through the South Gate tunnel into Loch Modan. The dwarven miners' league left the crates in the Silver Stream Mine at the north end of the loch; Tunnel Rat troggs hold the mine.", title = "The Silver Stream Mine"},
