	{{"complete", 9364, at = {1447, 29.94, 53.51}}, note = "Carry the Prismatic Shell back to the Ruins of Eldarath. Polymorph a Spitelash naga and wait a few seconds: it splits into small Polymorph Clones. Kill the clones quickly; the shell collects their essence.", title = "Polymorph Clones"},
	{{"turnin", 9364, at = {1447, 29.25, 40.21}, who = "Archmage Xylem"}, note = "Back to Sanath Lim-yo and up to the tower.", title = "Fragmented Magic"},
