Pathwise.RegisterRoute({category = "Class", classes = {"PRIEST"}, id = "forever/class/priest/benediction", levels = {60, 60}, map = 1423, title = "Benediction and Anathema", steps = {
	{{"have", 18665, 1, at = {1419, 35.54, 74.98}, name = "The Eye of Shadow"}, note = "You need The Eye of Divinity first: it comes from the Cache of the Firelord after Majordomo Executus in Molten Core. The Eye of Shadow drops from elite demons (Lord Kazzak, a world boss, always; Doomguard Commanders and Manahounds rarely); it binds when equipped, so buying one works too.", title = "The Eye of Shadow"},
	{{"level", 60}, {"accept", 7621, at = {1423, 17.21, 12.79}, who = "Eris Havenfire"}, {"turnin", 7621, at = {1423, 17.21, 12.79}, who = "Eris Havenfire"}, {"accept", 7622, at = {1423, 17.21, 12.79}, who = "Eris Havenfire"}, note = "Equip The Eye of Divinity to see Eris Havenfire, a ghost on the mountainside in the north-west of the Eastern Plaguelands. Come with full mana, Major Mana Potions and Oil of Immolation: if you fail, the event takes about two hours to return.", title = "Eris Havenfire"},
	{{"complete", 7622}, note = "Save 50 peasants before 15 die. Kill the skeletons that attack them, cure their diseases (the purple ones first) and heal the wounded with Renew. Friends may buff you beforehand but must stay out of the fight, or a demon appears and kills everyone.", title = "The Balance of Light and Shadow"},
