	{{"turnin", 2607, at = {1453, 80.06, 69.9}, who = "Doc Mixilpixil"}, {"accept", 2608, at = {1453, 80.06, 69.9}, who = "Doc Mixilpixil"}, {"complete", 2608}, {"turnin", 2608, at = {1453, 80.06, 69.9}, who = "Doc Mixilpixil"}, {"accept", 2609, at = {1453, 80.06, 69.9}, who = "Doc Mixilpixil"}, note = "Doc Mixilpixil works in the cellar of SI:7, the Barracks. Type /lay down beside him to be examined.", title = "Doc Mixilpixil"},
	{{"have", 3421, 1, from = {{1453, 69.34, 71.33, "Felicia Gump", "A"}}, name = "Simple Wildflowers"}, {"have", 3372, 1, from = {{1453, 80.28, 70.07, "Jasper Fel", "A"}, {1453, 55.9, 85.64, "Maria Lumere", "A"}, {1429, 41.25, 70.05, "Professor Thaddeus Paleo", "AH"}, {1429, 64.88, 69.19, "Dawn Brightstar", "A"}, {1429, 78.12, 72.96, "Antonio Perelli", "A"}, {1431, 18.04, 54.36, "Bliztik", "AH"}, {1436, 52.23, 52.83, "Christopher Hewen", "A"}, {1431, 73.8, 45.1, "Gunder Thornbush", "A"}}, name = "Leaded Vial"}, {"have", 4371, 1, from = {{1453, 62.43, 29.9, "Billibub Cogspinner", "A"}, {1431, 77.99, 48.33, "Herble Baubbletump", "A"}, {1418, 4.9, 94.7, "Yuka Screwspigot", "AH"}, {1426, 50.08, 49.42, "Loslor Rudge", "A"}, {1434, 50.98, 35.21, "Gnaz Blunderflame", "AH"}, {1426, 21.86, 31.86, "Namdo Bizzfizzle", "A"}, {1455, 67.84, 42.5, "Gearcutter Cogspinner", "A"}, {1437, 10.75, 56.75, "Neal Allen", "A"}}, name = "Bronze Tube"}, {"complete", 2609, at = {1453, 50.58, 60.14}}, note = "Everything is in Stormwind: the Gumps sell Simple Wildflowers, the Spool of Light Chartreuse Silk Thread lies in the city, and the nearest vendors sell a Leaded Vial and a Bronze Tube.", title = "The cure's ingredients"},
