Pathwise.RegisterRoute({category = "Class", classes = {"ROGUE"}, faction = "Horde", id = "forever/class/rogue/poisons-horde", levels = {20, 26}, map = 1454, title = "Poisons (Horde)", steps = {
	{{"level", 20}, {"accept", 2460, at = {1454, 43.05, 53.74}, who = "Shenthul"}, {"complete", 2460}, {"turnin", 2460, at = {1454, 43.05, 53.74}, who = "Shenthul"}, {"accept", 2458, at = {1454, 43.05, 53.74}, who = "Shenthul"}, note = "At 20 Shenthul stands in the Cleft of Shadow, the canyon under the Valley of Strength. Target him and type /salute.", title = "The Shattered Salute"},
	{{"note", "Use Flare Gun"}, {"turnin", 2458, at = {1413, 55.44, 5.56}, who = "Taskmaster Fizzule"}, {"accept", 2478, at = {1413, 55.44, 5.56}, who = "Taskmaster Fizzule"}, note = "Fly to the Crossroads and head north to the Venture Co. tower north of the Sludge Fen. In sight of the tower, fire the Flare Gun twice, then /salute Taskmaster Fizzule before he attacks you.", title = "Taskmaster Fizzule"},
	{{"complete", 2478, at = {1413, 54.8, 5.97}}, note = "Stay stealthed. Foreman Silixiz carries the tower key; Gallywix (elite) and his lockbox are at the top of the tower. Kill two each of the drones, patrollers and lookouts around it.", title = "Mission: Possible But Not Probable"},
	{{"turnin", 2478, at = {1454, 43.05, 53.74}, who = "Shenthul"}, {"accept", 2479, at = {1454, 43.05, 53.74}, who = "Shenthul"}, note = "Fly back to Orgrimmar.", title = "Back to Shenthul"},
	{{"goto", 1424, 60.14, 18.62, "Get the flight path at Tarren Mill", optional = true}, {"turnin", 2479, at = {1424, 61.63, 19.19}, who = "Serge Hinott"}, {"accept", 2480, at = {1424, 61.63, 19.19}, who = "Serge Hinott"}, {"complete", 2480}, {"turnin", 2480, at = {1424, 61.63, 19.19}, who = "Serge Hinott"}, note = "Take the zeppelin from Orgrimmar to the Undercity and head south through Silverpine Forest to Tarren Mill in Hillsbrad. Serge Hinott stands in Tarren Mill; wait beside him while he brews the cure.", title = "Serge Hinott"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"ROGUE"}, id = "forever/class/rogue/ravenholdt", levels = {24, 36}, map = 1424, title = "Ravenholdt", steps = {
	{{"level", 24}, {"accept", 6681}, note = "At 24 an Elegant Letter from Ravenholdt starts this; the data gives it to you through Master Mathias Shaw or Osborne the Night Man in Stormwind, or Gest or Ormok in Orgrimmar. The quest hands you the Seal of Ravenholdt for Fahrad.", title = "The Elegant Letter"},
	{{"complete", 6681, at = {1424, 78.64, 17.84}}, {"turnin", 6681, at = {1416, 84.45, 80.32}, who = "Fahrad"}, {"accept", 96779, at = {1416, 84.93, 80.38}, who = "Myrokos Silentform"}, {"accept", 6701, at = {1416, 85.27, 79.56}, optional = true, who = "Ravenholdt Guard"}, note = "Horde fly to Tarren Mill, Alliance to Southshore. The manor hides in the hills east of Tarren Mill, up a path into the Alterac Mountains; the Rite of Cunning is passing its way in.", title = "Ravenholdt Manor"},
	{{"complete", 96779, at = {1424, 79.2, 46.04}}, note = "Lord Tomas is inside Durnholde Keep, the Syndicate fortress in eastern Hillsbrad, south of the manor. Quick and quiet, says Myrokos.", title = "Lord Tomas"},
	{{"turnin", 96779, at = {1416, 84.93, 80.38}, who = "Myrokos Silentform"}, title = "Myrokos Silentform"},
	{{"level", 36}, {"accept", 96781, at = {1416, 84.93, 80.38}, who = "Myrokos Silentform"}, {"complete", 96781, at = {1416, 62.6, 46.9}}, note = "At 36, Myrokos sends you after Barton's scouting report. Barton leads a Syndicate party at Strahnbrad, in the east of the Alterac Mountains: pick his pocket, do not kill him.", title = "What's the Big Idea?"},
	{{"turnin", 96781, at = {1416, 84.93, 80.38}, who = "Myrokos Silentform"}, title = "Back to Myrokos"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"ROGUE"}, id = "forever/class/rogue/the-azure-key", levels = {50, 52}, map = 1416, title = "The Azure Key", steps = {
	{{"level", 50}, {"accept", 8233, at = {1453, 77.43, 65.31}, who = "Osborne the Night Man"}, note = "At 50 Osborne the Night Man in Stormwind's Old Town has it; so do Syurna in Darnassus and Hulfdan Blackbeard and Fenthwick in Ironforge.", only = {factions = {"Alliance"}}, title = "A Simple Request (Alliance)"},
	{{"level", 50}, {"accept", 8233, at = {1454, 43.9, 54.63}, who = "Ormok"}, note = "At 50 Ormok in the Cleft of Shadow has it; so does Miles Dexter in the Undercity's Rogues' Quarter.", only = {factions = {"Horde"}}, title = "A Simple Request (Horde)"},
	{{"turnin", 8233, at = {1416, 86.02, 78.88}, who = "Lord Jorach Ravenholdt"}, {"accept", 8234, at = {1416, 86.02, 78.88}, who = "Lord Jorach Ravenholdt"}, note = "Ravenholdt Manor hides in the hills east of Tarren Mill, up a path into the Alterac Mountains. Horde fly to Tarren Mill, Alliance to Southshore.", title = "Lord Jorach Ravenholdt"},
	{{"goto", 1447, 11.9, 77.59, "Get the flight path at Talrendis Point", only = {factions = {"Alliance"}}}, {"goto", 1447, 21.96, 49.62, "Get the flight path at Valormok", only = {factions = {"Horde"}}}, {"complete", 8234, at = {1447, 44.2, 26.6}}, note = "Alliance fly to Talrendis Point, Horde to Valormok. The Timbermaw Shamans in Azshara's northern hills drop the bag, about one in thirty.", title = "Sealed Azure Bag"},
	{{"turnin", 8234, at = {1447, 29.25, 40.21}, who = "Archmage Xylem"}, {"accept", 8235, at = {1447, 29.25, 40.21}, who = "Archmage Xylem"}, title = "Archmage Xylem"},
	{{"complete", 8235, at = {1447, 36.16, 67.86}}, note = "The Forest Oozes of southern Azshara drop the fragments.", title = "Encoded Fragments"},
	{{"turnin", 8235, at = {1447, 29.25, 40.21}, who = "Archmage Xylem"}, {"accept", 8236, at = {1447, 29.25, 40.21}, who = "Archmage Xylem"}, title = "Back to Xylem"},
	{{"complete", 8236, at = {1435, 69.9, 53.6}}, note = "Morphaz, a green drake, is an elite boss deep in the Sunken Temple, a level 50 dungeon: bring a group of five. The temple stands in the Pool of Tears; swim down to the entrance. Horde: fly to Stonard; Alliance: fly to Nethergarde Keep and ride on.", title = "Morphaz in the Sunken Temple"},
	{{"turnin", 8236, at = {1416, 86.02, 78.88}, who = "Lord Jorach Ravenholdt"}, title = "Lord Ravenholdt"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"ROGUE"}, id = "forever/class/rogue/the-eye-of-bhossca", levels = {25, 35}, map = 1421, title = "The Eye of Bhossca", steps = {
	{{"level", 25}, {"accept", 78676, at = {1421, 47.1, 70.95}, who = "Dead Drop"}, note = "The Dead Drop is a chest near Pyrewood Village in southern Silverpine, just south of Shadowfang Keep. After the horn job and C's next letter, check it for the new job. The data lists a minimum of 25, but beta players report receiving the invitation at 30 after the horn job and a city visit; this is not a guaranteed mail level. If no new note is offered, continue leveling and check after C writes.", title = "C's dead drop"},
	{{"goto", 1420, 82.6, 33.8, "Scarlet Monastery"}, {"note", "Solo route: Graveyard key, Library letter, Graveyard benches and coffer, then Library reliquary for the eye. Read the letter before the bench puzzle; check the disguise each time you change wings."}, note = "The monastery stands in the far north-east of Tirisfal Glades. Go in alone. Before entering, find the disguise in the chest by the outside stables. Recheck it after changing wings: stealth and suspicious actions can remove it. In the Graveyard, pickpocket a Scarlet Scryer for the Scryer's Key; use it on the Personal Letterbox in the Library and read the message. It sends you back to sit at both benches between the statues in the graveyard. Watch for the mechanism's messages, take the Reliquary Key from the stone coffer, then return to the Library for the locked reliquary. Avoid fighting through the instance.", title = "The Scarlet Monastery"},
	{{"turnin", 78676, at = {1421, 47.1, 70.95}, who = "Dead Drop"}, {"accept", 78699, at = {1421, 47.1, 70.95}, who = "Dead Drop"}, {"turnin", 78699, at = {1421, 47.1, 70.95}, who = "Dead Drop"}, note = "Place the eye in the Dead Drop near Pyrewood. Check a capital mailbox for C's payment letter on your next planned city visit, then return here for the reward quest. The payment may not be available immediately; do not repeat the infiltration just because the reward has not appeared.", title = "Back to the dead drop"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"ROGUE"}, id = "forever/class/rogue/the-horn-of-xelthos", levels = {23, 26}, map = 1421, title = "The Horn of Xelthos", steps = {
	{{"level", 23}, {"accept", 78261, at = {1421, 47.1, 70.95}, who = "Dead Drop"}, note = "The Dead Drop is a chest near Pyrewood Village in southern Silverpine, just south of Shadowfang Keep. Read C's note.", title = "C's dead drop"},
	{{"goto", 1442, 58.22, 51.74, "Talk to Veenix"}, {"accept", 78270, at = {1442, 58.22, 51.74}, who = "Veenix"}, {"have", 210187, 1, at = {1442, 59.44, 52.26}, name = "Venture Co. Work Order"}, {"turnin", 78270, at = {1442, 58.22, 51.74}, who = "Veenix"}, note = "Veenix, a goblin friendly to both factions, stands among the Venture Co. in the Windshear Crag, east Stonetalon. Horde fly to Sun Rock Retreat; Alliance to Stonetalon Peak. He wants a Venture Co. Work Order before he hands over explosives: the Venture Co. Loggers around him carry them.", title = "Veenix"},
	{{"complete", 78261, at = {1421, 44.8, 67.8}}, note = "Go in alone and use the Breaching Charge at the courtyard gate. If you know Vanish, bring Flash Powder and check its cooldown before entering; keep it ready for a failed approach. Pickpocket the sister in the dining hall for the Sister's Half-Key, then the brother in the room reached by turning right at the top of the stairs for the Brother's Half-Key. Combine them somewhere safe: this breaks stealth. Return to the courtyard stables and use the combined key on the chest for the horn. Stay clear of the nearby elites; the minimum quest level does not guarantee a safe approach.", title = "Shadowfang Keep"},
	{{"turnin", 78261, at = {1421, 47.1, 70.95}, who = "Dead Drop"}, {"accept", 78307, at = {1421, 47.1, 70.95}, who = "Dead Drop"}, {"turnin", 78307, at = {1421, 47.1, 70.95}, who = "Dead Drop"}, note = "Place the horn in the Dead Drop near Pyrewood. The payment may not appear immediately: check a capital mailbox for C's follow-up letter on your next planned city visit, then return to this chest for the reward quest. Do not repeat the dungeon just because the payment is not yet offered.", title = "Back to the dead drop"},
} })

