Pathwise.RegisterRoute({category = "Class", classes = {"SHAMAN"}, faction = "Horde", id = "forever/class/shaman/spirit-totem", levels = {50, 52}, map = 1454, title = "Spirit Totem and Da Voodoo", steps = {
	{{"accept", 8410, at = {1454, 38.66, 35.92}, who = "Sagorne Creststrider"}, note = "At 50 Sagorne Creststrider, the shaman trainer in the Valley of Wisdom, sends you to Bath'rah the Windwatcher.", only = {races = {"Orc", "Troll"}}, title = "Sagorne Creststrider"},
	{{"accept", 8410, at = {1456, 21.99, 18.8}, who = "Beram Skychaser"}, note = "At 50 Beram Skychaser, a shaman trainer in Thunder Bluff, sends you to Bath'rah the Windwatcher.", only = {races = {"Tauren", "Skyborne"}}, title = "Beram Skychaser"},
	{{"complete", 8410, at = {1417, 51.89, 50.62}}, note = "One each of Elemental Air, Fire, Earth and Water. The Exiles of Arathi Highlands drop them, one element each, about one kill in ten: Thundering (air), Burning (fire), Rumbling (earth) and Cresting (water). Or buy them at the auction house.", title = "The four elements"},
	{{"turnin", 8410, at = {1416, 80.5, 66.92}, who = "Bath'rah the Windwatcher"}, {"accept", 8412, at = {1416, 80.5, 66.92}, who = "Bath'rah the Windwatcher"}, note = "Bath'rah camps in the east of Alterac Mountains, north-east of Tarren Mill.", title = "Bath'rah the Windwatcher"},
	{{"complete", 8412, at = {1422, 31.08, 58.54}}, note = "In the Western Plaguelands, the Venom Mist Lurkers drop the Bloodshot Spider Eye and the Diseased Black Bears the Thick Black Claw (about one kill in five each). Carrion birds can drop either, so keep what they give you on the way.", title = "Spider eye and bear claw"},
	{{"turnin", 8412, at = {1416, 80.5, 66.92}, who = "Bath'rah the Windwatcher"}, {"accept", 8413, at = {1416, 80.5, 66.92}, who = "Bath'rah the Windwatcher"}, title = "Bath'rah the Windwatcher"},
	{{"complete", 8413, at = {1435, 69.9, 53.6}}, note = "The Sunken Temple (Temple of Atal'Hakkar) lies under the Pool of Tears; the arrow points at its entrance. Gasher or Zul'Lor drop the Amber Voodoo Feather, Hukku or Mijan the Blue, Zolo or Loro the Green: all six are elite trolls inside. Bring a group.", title = "The Sunken Temple"},
	{{"turnin", 8413, at = {1416, 80.5, 66.92}, who = "Bath'rah the Windwatcher"}, title = "Bath'rah the Windwatcher"},
} })

