Pathwise.RegisterRoute({category = "Class", classes = {"WARLOCK"}, id = "forever/class/warlock/orb-of-orahil", levels = {35, 40}, map = 1413, title = "Orb of Orahil", steps = {
	{{"level", 35}, {"accept", 4968, at = {1453, 39.24, 84.96}, who = "Demisette Cloyce"}, note = "At 35 Demisette Cloyce in the Slaughtered Lamb, in the Mage Quarter, sends you to Menara Voidrender in Ratchet.", only = {races = {"Human"}}, title = "Knowledge of the Orb of Orahil (Stormwind)"},
	{{"level", 35}, {"accept", 4965, at = {1455, 50.35, 5.66}, who = "Briarthorn"}, note = "At 35 Briarthorn in Ironforge sends you to Menara Voidrender in Ratchet.", only = {races = {"Gnome"}}, title = "Knowledge of the Orb of Orahil (Ironforge)"},
	{{"level", 35}, {"accept", 4967, at = {1454, 48.47, 45.43}, who = "Zevrost"}, note = "At 35 Zevrost in the Cleft of Shadow sends you to Menara Voidrender in Ratchet.", only = {races = {"Orc", "Troll"}}, title = "Knowledge of the Orb of Orahil (Orgrimmar)"},
	{{"level", 35}, {"accept", 4969, at = {1458, 86.21, 15.93}, who = "Kaal Soulreaper"}, note = "At 35 Kaal Soulreaper in the Magic Quarter sends you to Menara Voidrender in Ratchet. The zeppelin from Tirisfal Glades flies to Durotar.", only = {races = {"Scourge"}}, title = "Knowledge of the Orb of Orahil (Undercity)"},
	{{"turnin", 4968, at = {1413, 62.51, 35.45}, only = {races = {"Human"}}, who = "Menara Voidrender"}, {"turnin", 4965, at = {1413, 62.51, 35.45}, only = {races = {"Gnome"}}, who = "Menara Voidrender"}, {"turnin", 4967, at = {1413, 62.51, 35.45}, only = {races = {"Orc", "Troll"}}, who = "Menara Voidrender"}, {"turnin", 4969, at = {1413, 62.51, 35.45}, only = {races = {"Scourge"}}, who = "Menara Voidrender"}, {"accept", 1799, at = {1413, 62.51, 35.45}, who = "Menara Voidrender"}, note = "Menara Voidrender and her two acolytes stand in the tower on the hill above Ratchet, beside Strahad Farsan.", title = "Menara Voidrender"},
	{{"accept", 4962, at = {1413, 62.64, 35.3}, who = "Acolyte Wytula"}, {"accept", 4963, at = {1413, 62.56, 35.23}, who = "Acolyte Magaz"}, note = "Pick one acolyte: you can take only one of their quests. Acolyte Wytula's felhound path ends with the Orb or Staff of Dar'Orahil, Acolyte Magaz's infernal path with the Orb or Staff of Noh'Orahil. The guide follows the one you take.", title = "Choose an acolyte"},
	{{"complete", 1799, at = {1443, 66.49, 77.94}}, {"complete", 4962, at = {1443, 52.91, 68.14}}, {"complete", 4963, at = {1443, 54.31, 71.14}}, note = "The demons of Mannoroc Coven, in southern Desolace, have all you need. Burning Blade Summoners carry the Infernal Orb. On the felhound path, use the Felhas Ruby on a Mana Eater, a felhound, and kill it for its spirit; on the infernal path, use the Infus Emerald on a Lesser Infernal and kill it.", title = "Mannoroc Coven"},
	{{"turnin", 4962, at = {1413, 62.51, 35.45}, who = "Menara Voidrender"}, {"turnin", 4963, at = {1413, 62.51, 35.45}, who = "Menara Voidrender"}, note = "Back to Menara Voidrender in the tower above Ratchet with the spirit first: Tabetha's cleansing follows it.", title = "The demon's spirit"},
	{{"turnin", 1799, at = {1445, 46.06, 57.09}, who = "Tabetha"}, {"accept", 4961, at = {1445, 46.06, 57.09}, who = "Tabetha"}, {"complete", 4961, at = {1445, 45.79, 56.97}}, {"turnin", 4961, at = {1445, 46.06, 57.09}, who = "Tabetha"}, {"accept", 4976, at = {1445, 46.06, 57.09}, who = "Tabetha"}, note = "Tabetha lives at her farm in western Dustwallow Marsh. She calls the Demon of the Orb out of the Infernal Orb; it is elite: grouping up is advised.", title = "Tabetha"},
	{{"turnin", 4976, at = {1413, 62.51, 35.45}, who = "Menara Voidrender"}, {"accept", 4964, at = {1413, 62.51, 35.45}, who = "Menara Voidrender"}, {"complete", 4964}, {"turnin", 4964, at = {1413, 62.51, 35.45}, who = "Menara Voidrender"}, note = "Back to Menara in the tower above Ratchet with the cleansed orb. On the felhound path, wait while she completes the Orb of Dar'Orahil, then speak to her again.", title = "The Orb of Dar'Orahil"},
	{{"accept", 4975, at = {1413, 62.51, 35.45}, who = "Menara Voidrender"}, {"complete", 4975}, {"turnin", 4975, at = {1413, 62.51, 35.45}, who = "Menara Voidrender"}, note = "On the infernal path, wait while Menara completes the Orb of Noh'Orahil, then speak to her again.", title = "The Orb of Noh'Orahil"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"WARLOCK"}, id = "forever/class/warlock/orb-of-soranruk", levels = {25, 30}, map = 1413, title = "Orb of Soran'ruk", steps = {
	{{"level", 20}, {"accept", 1740, at = {1413, 49.31, 57.21}, who = "Doan Karhan"}, note = "Doan Karhan camps in the southern Barrens, east of the road north-east of Camp Taurajo.", title = "Doan Karhan"},
	{{"complete", 1740, at = {1440, 14.5, 14.2}}, note = "The Twilight Acolytes inside Blackfathom Deeps, a level 24-32 dungeon, each drop a Soran'ruk Fragment: bring a group. The entrance is in the ruins on the north-west coast of Ashenvale.", title = "Blackfathom Deeps"},
	{{"complete", 1740, at = {1421, 44.8, 67.8}}, note = "The Shadowfang Darksouls inside Shadowfang Keep, a level 20-30 dungeon, drop the Large Fragment about one time in five: bring a group. The keep stands south of the Sepulcher.", title = "Shadowfang Keep"},
	{{"turnin", 1740, at = {1413, 49.31, 57.21}, who = "Doan Karhan"}, title = "Back to Doan Karhan"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"WARLOCK"}, id = "forever/class/warlock/shard-of-the-green-flame", levels = {50, 56}, map = 1448, title = "Shard of the Green Flame", steps = {
