	{{"complete", 7602, at = {1448, 40.01, 49.15}}, note = "The Jaedenar Legionnaires, a short way west of Niby, carry Jaedenar's essence.", title = "Jaedenar"},
	{{"complete", 7602, at = {1447, 61.42, 20.92}}, note = "The Legashi satyrs of northern Azshara carry Azshara's essence.", title = "Azshara"},
	{{"complete", 7602, at = {1419, 58.52, 51.23}}, note = "The Felguard Sentries around the Dark Portal, in southern Blasted Lands, carry its essence.", title = "The Dark Portal"},
	{{"turnin", 7602, at = {1448, 41.36, 45.02}, who = "Impsy"}, {"accept", 7603, at = {1448, 41.36, 45.02}, who = "Impsy"}, title = "Impsy"},
	{{"note", "Use Fel Fire"}, {"complete", 7603, at = {1448, 45.7, 34.76}}, note = "Kroshius' remains lie in Shatter Scar Vale, north of Niby. Use the Fel Fire beside them and kill the infernal when he wakes. Kroshius is elite: grouping up is advised.", title = "Kroshius"},
	{{"turnin", 7603, at = {1448, 41.38, 44.85}, who = "Niby the Almighty"}, title = "Back to Niby"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"WARLOCK"}, id = "forever/class/warlock/tome-of-sacrifice", levels = {60, 60}, map = 1419, title = "Tome of Sacrifice", steps = {
