	{{"complete", 7581, at = {1444, 76.9, 37.4}}, note = "The Wildspawn satyrs of the Warpwood Quarter, Dire Maul's eastern wing, carry the blood. The back door at Lariss Pavilion, north of Camp Mojache, needs the Crescent Key; otherwise go in by Dire Maul's main entrance. Bring a group.", title = "Satyr Blood"},
	{{"complete", 7582, at = {1452, 58.3, 82.25}}, note = "The Hederine demons hold Darkwhisper Gorge, in southern Winterspring. They are elite: grouping up is advised.", title = "Tears of the Hederine"},
	{{"turnin", 7581, at = {1419, 34.13, 50.14}, who = "Daio the Decrepit"}, {"turnin", 7582, at = {1419, 34.13, 50.14}, who = "Daio the Decrepit"}, {"accept", 7583, at = {1419, 34.13, 50.14}, who = "Daio the Decrepit"}, {"note", "Use Glowing Crystal Prison"}, {"complete", 7583, at = {1419, 34.55, 63.73}}, note = "Hand both in to Daio, then find the Doomguard Commander in the Tainted Scar and use the Glowing Crystal Prison on him. He is elite and fights to escape: grouping up is advised.", title = "Suppression"},
	{{"turnin", 7583, at = {1419, 34.13, 50.14}, who = "Daio the Decrepit"}, title = "Back to Daio"},
