Pathwise.RegisterRoute({category = "Class", classes = {"WARRIOR"}, faction = "Horde", id = "forever/class/warrior/brutal-armor", levels = {20, 32}, map = 1413, title = "Brutal Armor", steps = {
	{{"level", 20}, {"accept", 1823, at = {1454, 80.39, 32.38}, who = "Sorek"}, note = "At 20, Sorek in the Valley of Honor sends you to Ruga Ragetotem in Camp Taurajo.", only = {races = {"Orc", "Troll", "Skyborne"}}, title = "Speak with Ruga (Orgrimmar)"},
	{{"level", 20}, {"accept", 1823, at = {1456, 57.24, 87.37}, who = "Torm Ragetotem"}, note = "At 20, Torm Ragetotem, the warrior trainer of Thunder Bluff, sends you to Ruga Ragetotem in Camp Taurajo.", only = {races = {"Tauren"}}, title = "Speak with Ruga (Thunder Bluff)"},
	{{"level", 20}, {"accept", 1823, at = {1458, 47.4, 17.29}, who = "Baltus Fowler"}, note = "At 20, Baltus Fowler, a warrior trainer of the Undercity, sends you to Ruga Ragetotem in Camp Taurajo.", only = {races = {"Scourge"}}, title = "Speak with Ruga (Undercity)"},
	{{"turnin", 1823, at = {1413, 44.67, 59.42}, who = "Ruga Ragetotem"}, {"accept", 1824, at = {1413, 44.67, 59.42}, who = "Ruga Ragetotem"}, {"complete", 1824, at = {1413, 45.11, 68.95}}, {"turnin", 1824, at = {1413, 44.67, 59.42}, who = "Ruga Ragetotem"}, {"accept", 1825, at = {1413, 44.67, 59.42}, who = "Ruga Ragetotem"}, note = "Fly to Camp Taurajo. South of the camp the Silithid Mounds dot the Field of Giants: the silithid there carry the Twitching Antennae.", title = "Trial at the Field of Giants"},
	{{"turnin", 1825, at = {1413, 57.23, 30.34}, who = "Thun'grim Firegaze"}, {"accept", 1838, at = {1413, 57.23, 30.34}, who = "Thun'grim Firegaze"}, note = "Thun'grim camps beside the road east of the Crossroads. Brutal Armor is a level 30 quest; you can take it now and gather for it on the way.", title = "Thun'grim Firegaze"},
	{{"complete", 1838, at = {1413, 42.9, 90.2}}, note = "Roogug is an elite quilboar inside Razorfen Kraul, the dungeon at the south end of the Barrens; he drops the Vial of Phlogiston. Razorfen Kraul is a dungeon: grouping up is advised.", title = "Roogug in Razorfen Kraul"},
	{{"complete", 1838, at = {1442, 71.76, 60.29}}, note = "The Windshear Mine lies at the east end of Windshear Crag in Stonetalon. Its kobolds drop the Smoky Iron Ingots.", title = "Windshear Mine"},
	{{"complete", 1838, at = {1424, 30, 54.97}}, note = "The Hillsbrad Miners work the mine in the west of Hillsbrad Foothills; they drop the Powdered Azurite. Take the zeppelin from Orgrimmar to Tirisfal Glades and head south through Silverpine Forest.", title = "Hillsbrad Miners"},
	{{"complete", 1838, at = {1454, 55.9, 62.7}}, note = "Miners smelt Iron Bars from Iron Ore (Mining 125); everyone else buys them at the auction house in Orgrimmar.", title = "Iron Bars"},
	{{"turnin", 1838, at = {1413, 57.23, 30.34}, who = "Thun'grim Firegaze"}, {"accept", 1848, at = {1413, 57.23, 30.34}, who = "Thun'grim Firegaze"}, {"turnin", 1848, at = {1413, 57.23, 30.34}, who = "Thun'grim Firegaze"}, {"accept", 1839, at = {1413, 57.23, 30.34}, who = "Thun'grim Firegaze"}, {"accept", 1840, at = {1413, 57.23, 30.34}, who = "Thun'grim Firegaze"}, {"accept", 1841, at = {1413, 57.23, 30.34}, who = "Thun'grim Firegaze"}, note = "Back to Thun'grim beside the road east of the Crossroads. Brutal Hauberk is the first piece; he then sends you to three crafters for the rest.", title = "Brutal Hauberk"},
	{{"turnin", 1839, at = {1411, 56.31, 74.33}, who = "Ula'elek"}, {"accept", 1842, at = {1411, 56.31, 74.33}, who = "Ula'elek"}, note = "Ula'elek is in Sen'jin Village on the Durotar coast.", title = "Ula'elek"},
	{{"complete", 1842, at = {1440, 78.29, 45.29}}, note = "The Xavian satyrs camp in eastern Ashenvale, with the Felmusk satyrs further west; both drop Uncloven Satyr Hooves.", title = "Satyr Hooves"},
	{{"turnin", 1842, at = {1411, 56.31, 74.33}, who = "Ula'elek"}, {"accept", 1843, at = {1411, 56.31, 74.33}, who = "Ula'elek"}, {"turnin", 1843, at = {1411, 56.31, 74.33}, who = "Ula'elek"}, title = "Brutal Gauntlets"},
	{{"turnin", 1840, at = {1456, 38.99, 55.98}, who = "Orm Stonehoof"}, {"accept", 1844, at = {1456, 38.99, 55.98}, who = "Orm Stonehoof"}, title = "Orm Stonehoof"},
	{{"complete", 1844, at = {1442, 33.64, 74.66}}, note = "The Chimaera Matriarch roams the south-west of Stonetalon near the Fledgling and Young Chimaeras; she drops the Galvanized Horn.", title = "Chimaeric Horn"},
	{{"turnin", 1844, at = {1456, 38.99, 55.98}, who = "Orm Stonehoof"}, {"accept", 1845, at = {1456, 38.99, 55.98}, who = "Orm Stonehoof"}, {"turnin", 1845, at = {1456, 38.99, 55.98}, who = "Orm Stonehoof"}, title = "Brutal Helm"},
	{{"turnin", 1841, at = {1458, 62.14, 39.14}, who = "Velora Nitely"}, {"accept", 1846, at = {1458, 62.14, 39.14}, who = "Velora Nitely"}, note = "Take the zeppelin from Orgrimmar to Tirisfal Glades; the Undercity lies below the Ruins of Lordaeron.", title = "Velora Nitely"},
	{{"complete", 1846, at = {1437, 45.72, 44.78}}, note = "The Dragonmaw orcs camp in the middle of the Wetlands, south of the road; Raiders, Swamprunners, Centurions, Shadowwarders and Bonewarders all drop the Sturdy Dragonmaw Shinbones.", title = "Dragonmaw Shinbones"},
	{{"turnin", 1846, at = {1458, 62.14, 39.14}, who = "Velora Nitely"}, {"accept", 1847, at = {1458, 62.14, 39.14}, who = "Velora Nitely"}, {"turnin", 1847, at = {1458, 62.14, 39.14}, who = "Velora Nitely"}, title = "Brutal Legguards"},
