Pathwise.RegisterRoute({category = "Class", classes = {"WARRIOR"}, faction = "Alliance", id = "forever/class/warrior/fire-hardened-armor", levels = {20, 30}, map = 1433, title = "Fire Hardened Armor", steps = {
