	{{"level", 20}, {"accept", 1698, at = {1455, 70.34, 90.65}, who = "Kelv Sternhammer"}, note = "At 20, Kelv Sternhammer, the warrior trainer of Ironforge, sends you to Yorus Barleybrew in Redridge.", only = {races = {"Dwarf", "Gnome"}}, title = "Yorus Barleybrew (Ironforge)"},
	{{"level", 20}, {"accept", 1698, at = {1457, 58.94, 35.35}, who = "Darnath Bladesinger"}, note = "At 20, Darnath Bladesinger, the warrior trainer of Darnassus, sends you to Yorus Barleybrew in Redridge.", only = {races = {"NightElf"}}, title = "Yorus Barleybrew (Darnassus)"},
