	{{"turnin", 1702, at = {1453, 64.62, 37.23}, who = "Furen Longbeard"}, {"accept", 1701, at = {1453, 64.62, 37.23}, who = "Furen Longbeard"}, note = "Furen Longbeard works in the Dwarven District of Stormwind. He keeps the Cask of Scalder and gives you Furen's Favor, a shield; Fire Hardened Mail is a level 28 quest.", title = "The Shieldsmith"},
	{{"complete", 1701, at = {1437, 52.65, 63.09}}, note = "The Leech Stalkers and Cave Stalkers crawl around 46,61 in the middle of the Wetlands; they drop the Scorched Spider Fang.", title = "Scorched Spider Fangs"},
	{{"complete", 1701, at = {1442, 32.99, 72.07}}, note = "The Fledgling and Young Chimaeras roam the south-west of Stonetalon, with the Chimaera Matriarch among them: the young ones drop the Charred Horn, the Matriarch the Galvanized Horn.", title = "Charred and Galvanized Horns"},
	{{"complete", 1701, at = {1413, 42.9, 90.2}}, note = "Roogug is an elite quilboar inside Razorfen Kraul, the dungeon at the south end of the Barrens; he drops the Vial of Phlogiston. Razorfen Kraul is a dungeon: grouping up is advised.", title = "Roogug in Razorfen Kraul"},
	{{"turnin", 1701, at = {1453, 64.62, 37.23}, who = "Furen Longbeard"}, {"accept", 1782, at = {1453, 64.62, 37.23}, who = "Furen Longbeard"}, {"turnin", 1782, at = {1453, 64.62, 37.23}, who = "Furen Longbeard"}, {"accept", 1700, at = {1453, 64.62, 37.23}, only = {races = {"Human"}}, who = "Furen Longbeard"}, {"accept", 1703, at = {1453, 64.62, 37.23}, only = {races = {"NightElf"}}, who = "Furen Longbeard"}, {"accept", 1704, at = {1453, 64.62, 37.23}, only = {races = {"Dwarf", "Gnome"}}, who = "Furen Longbeard"}, note = "Back to Furen Longbeard in the Dwarven District. He sends you on to a smith of your own race.", title = "Furen's Armor"},
	{{"turnin", 1700, at = {1453, 59.73, 33.78}, who = "Grimand Elmore"}, {"accept", 1705, at = {1453, 59.73, 33.78}, who = "Grimand Elmore"}, note = "Grimand Elmore is in Stormwind, a short walk from Furen.", only = {races = {"Human"}}, title = "Grimand Elmore"},
	{{"complete", 1705, at = {1431, 64.05, 58.91}}, note = "The Nightbane worgen of Duskwood drop the Burning Blood. Gutspill walks in the far south-east of Duskwood and carries the Burning Rock.", only = {races = {"Human"}}, title = "Burning Blood"},
	{{"turnin", 1705, at = {1453, 59.73, 33.78}, who = "Grimand Elmore"}, {"accept", 1706, at = {1453, 59.73, 33.78}, who = "Grimand Elmore"}, {"turnin", 1706, at = {1453, 59.73, 33.78}, who = "Grimand Elmore"}, only = {races = {"Human"}}, title = "Grimand's Armor"},
	{{"turnin", 1703, at = {1457, 59.51, 45.38}, who = "Mathiel"}, {"accept", 1710, at = {1457, 59.51, 45.38}, who = "Mathiel"}, note = "Mathiel is a smith in Darnassus.", only = {races = {"NightElf"}}, title = "Mathiel"},
	{{"complete", 1710, at = {1441, 12.05, 37.11}}, note = "The Sunscorched Shells lie along the western edge of Thousand Needles.", only = {races = {"NightElf"}}, title = "Sunscorched Shells"},
	{{"turnin", 1710, at = {1457, 59.51, 45.38}, who = "Mathiel"}, {"accept", 1711, at = {1457, 59.51, 45.38}, who = "Mathiel"}, {"turnin", 1711, at = {1457, 59.51, 45.38}, who = "Mathiel"}, only = {races = {"NightElf"}}, title = "Mathiel's Armor"},
	{{"turnin", 1704, at = {1455, 67.92, 46.1}, who = "Klockmort Spannerspan"}, {"accept", 1708, at = {1455, 67.92, 46.1}, who = "Klockmort Spannerspan"}, note = "Ride the Deeprun Tram from Stormwind to Ironforge.", only = {races = {"Dwarf", "Gnome"}}, title = "Klockmort Spannerspan"},
	{{"complete", 1708, at = {1437, 9.31, 69.14}}, note = "The Iron Coral grows along the Wetlands' west coast, south of Menethil Harbor.", only = {races = {"Dwarf", "Gnome"}}, title = "Iron Coral"},
	{{"turnin", 1708, at = {1455, 67.92, 46.1}, who = "Klockmort Spannerspan"}, {"accept", 1709, at = {1455, 67.92, 46.1}, who = "Klockmort Spannerspan"}, {"turnin", 1709, at = {1455, 67.92, 46.1}, who = "Klockmort Spannerspan"}, only = {races = {"Dwarf", "Gnome"}}, title = "Klockmort's Creation"},
