Pathwise.RegisterRoute({category = "Class", classes = {"WARRIOR"}, faction = "Horde", id = "forever/class/warrior/heirloom-weapon", levels = {10, 11}, map = 1420, races = {"Scourge"}, title = "Heirloom Weapon", steps = {
