	{{"turnin", 1820, at = {1420, 61.72, 52.29}, who = "Coleman Farthing"}, {"accept", 1821, at = {1420, 61.72, 52.29}, who = "Coleman Farthing"}, note = "Coleman Farthing is in the inn, the Gallows' End Tavern, in Brill.", title = "Coleman Farthing"},
	{{"complete", 1821, at = {1420, 51.68, 25.69}}, note = "The four Agamand Weapon Racks stand among the buildings of Agamand Mills, north of Brill. The mills' undead attack on sight.", title = "Agamand Mills"},
	{{"turnin", 1821, at = {1420, 61.72, 52.29}, who = "Coleman Farthing"}, {"accept", 1822, at = {1420, 61.72, 52.29}, who = "Coleman Farthing"}, {"turnin", 1822, at = {1420, 61.72, 52.29}, who = "Coleman Farthing"}, title = "Back to Coleman Farthing"},
} })

