	{{"turnin", 8424, at = {1435, 34.29, 66.14}, who = "Fallen Hero of the Horde"}, {"accept", 8425, at = {1435, 34.29, 66.14}, who = "Fallen Hero of the Horde"}, title = "Voodoo Feathers"},
	{{"complete", 8425, at = {1435, 69.9, 53.6}}, note = "The Sunken Temple lies under the Pool of Tears in the east of the Swamp of Sorrows. Each of the six Atal'ai trolls on the balcony drops a voodoo feather: Gasher or Zul'Lor the amber, Hukku or Mijan the blue, Zolo or Loro the green. The Sunken Temple is a dungeon and the trolls are elite: grouping up is advised.", title = "The Sunken Temple"},
