	{{"level", 30}, {"accept", 1718, at = {1455, 70.34, 90.65}, who = "Kelv Sternhammer"}, note = "At 30, Kelv Sternhammer, the warrior trainer of Ironforge, sends you to Klannoc Macleod on Fray Island in the Barrens.", only = {races = {"Dwarf", "Gnome"}}, title = "The Islander (Ironforge)"},
	{{"level", 30}, {"accept", 1718, at = {1454, 80.39, 32.38}, who = "Sorek"}, note = "At 30, Sorek in the Valley of Honor sends you to Klannoc Macleod on Fray Island in the Barrens.", only = {factions = {"Horde"}, races = {"Orc", "Troll", "Skyborne"}}, title = "The Islander (Orgrimmar)"},
