	{{"level", 30}, {"accept", 1718, at = {1458, 47.4, 17.29}, who = "Baltus Fowler"}, note = "At 30, Baltus Fowler, a warrior trainer of the Undercity, sends you to Klannoc Macleod on Fray Island in the Barrens.", only = {races = {"Scourge"}}, title = "The Islander (Undercity)"},
	{{"turnin", 1718, at = {1413, 68.62, 49.16}, who = "Klannoc Macleod"}, {"accept", 1719, at = {1413, 68.62, 49.16}, who = "Klannoc Macleod"}, {"complete", 1719}, {"turnin", 1719, at = {1413, 68.62, 49.16}, who = "Klannoc Macleod"}, {"accept", 1791, at = {1413, 68.62, 49.16}, who = "Klannoc Macleod"}, note = "Head south along the coast from Ratchet to Fray Island. Klannoc Macleod stands by the arena: step on the grate to start the fight; the challengers come one at a time, then Big Will (33).", title = "The Affray"},
	{{"turnin", 1791, at = {1416, 80.5, 66.92}, who = "Bath'rah the Windwatcher"}, {"accept", 1712, at = {1416, 80.5, 66.92}, who = "Bath'rah the Windwatcher"}, {"accept", 1714, at = {1416, 79.32, 66.8}, who = "Bath'rah's Cauldron"}, note = "Bath'rah the Windwatcher camps in the south-east of Alterac Mountains, above Hillsbrad Foothills; his cauldron stands beside him. He asks for a Liferoot, a Bloodscalp Tusk and the Essence of the Exile, which his cauldron brews from three charms.", title = "Bath'rah the Windwatcher"},
	{{"complete", 1714, at = {1417, 25.61, 30.4}}, note = "Three kinds of elemental exiles roam Arathi Highlands: Burning Exiles in the north-west, Thundering Exiles in the middle, Cresting Exiles in the north-east. Each drops its charm.", title = "The exiles of Arathi"},
	{{"turnin", 1714, at = {1416, 79.32, 66.8}, who = "Bath'rah's Cauldron"}, {"complete", 1712, at = {1416, 77.21, 64.4}}, title = "Essence of the Exile"},
	{{"complete", 1712, at = {1434, 32.26, 17.17}}, note = "The Bloodscalp trolls hold the north-west of Stranglethorn Vale; they drop the Bloodscalp Tusk.", title = "Bloodscalp Tusk"},
	{{"turnin", 1712, at = {1416, 80.5, 66.92}, who = "Bath'rah the Windwatcher"}, {"accept", 1713, at = {1416, 80.5, 66.92}, who = "Bath'rah the Windwatcher"}, {"complete", 1713, at = {1416, 80.32, 62.14}}, {"turnin", 1713, at = {1416, 80.5, 66.92}, who = "Bath'rah the Windwatcher"}, {"accept", 1792, at = {1416, 80.5, 66.92}, who = "Bath'rah the Windwatcher"}, {"turnin", 1792, at = {1416, 80.5, 66.92}, who = "Bath'rah the Windwatcher"}, note = "Cyclonian waits just north of Bath'rah's camp and carries the Whirlwind Heart. Cyclonian is elite: grouping up is advised.", title = "The Summoning"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"PALADIN"}, faction = "Alliance", id = "forever/collectibles/mounts/alliance/paladin-charger", levels = {60, 60}, map = 1453, title = "Paladin Charger", steps = {
	{{"level", 60}, {"accept", 7670, at = {1455, 23.13, 6.14}, who = "Brandur Ironhammer"}, note = "At 60 Brandur Ironhammer in the Mystic Ward sends you to Lord Grayson Shadowbreaker in Stormwind's Cathedral of Light.", only = {races = {"Dwarf"}}, title = "Lord Grayson Shadowbreaker (Ironforge)"},
	{{"level", 60}, {"accept", 7638, at = {1453, 50.48, 47.49}, only = {races = {"Human"}}, who = "Duthorian Rall"}, {"turnin", 7638, at = {1453, 48.43, 50.22}, only = {races = {"Human"}}, who = "Lord Grayson Shadowbreaker"}, {"turnin", 7670, at = {1453, 48.43, 50.22}, only = {races = {"Dwarf"}}, who = "Lord Grayson Shadowbreaker"}, {"accept", 7637, at = {1453, 48.43, 50.22}, who = "Lord Grayson Shadowbreaker"}, note = "The Summon Charger chain is long: it takes you through Stratholme, Dire Maul and Scholomance, and costs about 350 gold in donations on top of the materials. Lord Grayson stands in the Cathedral of Light.", title = "Lord Grayson Shadowbreaker"},
	{{"turnin", 7637, at = {1455, 24.73, 8.16}, who = "High Priest Rohan"}, {"accept", 7639, at = {1455, 24.73, 8.16}, who = "High Priest Rohan"}, note = "High Priest Rohan is in Ironforge's Mystic Ward. Bring 150 gold: the censer is yours for a donation.", title = "High Priest Rohan"},
	{{"turnin", 7639, at = {1453, 48.43, 50.22}, who = "Lord Grayson Shadowbreaker"}, {"accept", 7640, at = {1453, 48.43, 50.22}, who = "Lord Grayson Shadowbreaker"}, title = "Back to Lord Grayson"},
	{{"complete", 7640, at = {1423, 11.61, 21.36}}, note = "Terrordale lies in the far north-west of the Eastern Plaguelands, by the Western Plaguelands border. Use the Exorcism Censer there to drive out the spirits, then defeat them.", title = "Exorcising Terrordale"},
	{{"turnin", 7640, at = {1453, 48.43, 50.22}, who = "Lord Grayson Shadowbreaker"}, {"accept", 7641, at = {1453, 48.43, 50.22}, who = "Lord Grayson Shadowbreaker"}, title = "Lord Grayson Shadowbreaker"},
	{{"turnin", 7641, at = {1453, 59.73, 33.78}, who = "Grimand Elmore"}, {"accept", 7642, at = {1453, 59.73, 33.78}, who = "Grimand Elmore"}, note = "Grimand Elmore works in Stormwind's Dwarven District.", title = "Grimand Elmore"},
	{{"complete", 7642, at = {1453, 61.2, 71.3}}, note = "Runecloth drops from humanoids around level 50 and up; Arthas' Tears is an herb of the Plaguelands and Felwood; Arcanite Bars are an Alchemy transmute. The Auction House in Stormwind's Trade District sells all three, and so do crafters.", title = "Grimand's materials"},
	{{"goto", 1423, 26.5, 10.4, "Stratholme"}, {"complete", 7642, at = {1423, 26.5, 10.4}}, note = "Stratholme is a group of five, level 58-60, at the north end of the Eastern Plaguelands. The Supply Crates scattered through the city hold the Stratholme Holy Water.", title = "Stratholme Holy Water"},
	{{"turnin", 7642, at = {1453, 59.73, 33.78}, who = "Grimand Elmore"}, {"accept", 7648, at = {1453, 59.73, 33.78}, who = "Grimand Elmore"}, note = "Bring 150 gold for Grimand along with the materials.", title = "Grimand Elmore"},
	{{"turnin", 7648, at = {1453, 48.43, 50.22}, who = "Lord Grayson Shadowbreaker"}, {"accept", 7643, at = {1453, 48.43, 50.22}, who = "Lord Grayson Shadowbreaker"}, title = "Lord Grayson Shadowbreaker"},
	{{"have", 13724, 20, at = {1422, 42.84, 83.72}, name = "Enriched Manna Biscuit"}, note = "The Argent Dawn quartermasters sell the biscuits in fives once the Argent Dawn is Friendly with you: Argent Quartermaster Lightspark at Chillwind Camp, Quartermaster Miranda Breechlock at Light's Hope Chapel, Argent Quartermaster Hasana at the Bulwark.", title = "Enriched Manna Biscuits"},
	{{"accept", 7645, at = {1424, 52.19, 55.48}, who = "Merideth Carlson"}, {"have", 13724, 20, at = {1422, 42.84, 83.72}, name = "Enriched Manna Biscuit"}, {"turnin", 7645, at = {1424, 52.19, 55.48}, who = "Merideth Carlson"}, note = "Merideth Carlson breeds horses in Southshore. She also wants 50 gold.", title = "Merideth Carlson"},
	{{"goto", 1444, 59.2, 45.1, "Dire Maul"}, {"note", "Kill Tendris Warpwood"}, {"turnin", 7643, at = {1444, 59.2, 45.1}, who = "Ancient Equine Spirit"}, {"accept", 7644, at = {1444, 59.2, 45.1}, who = "Ancient Equine Spirit"}, note = "Dire Maul lies in central Feralas; Tendris Warpwood guards the start of the West wing. Defeat him to free the Ancient Equine Spirit, feed it the Manna-Enriched Horse Feed and hand it the Arcanite Barding to bless. Bring a group.", title = "Dire Maul: Tendris Warpwood"},
	{{"turnin", 7644, at = {1453, 48.43, 50.22}, who = "Lord Grayson Shadowbreaker"}, {"accept", 7646, at = {1453, 48.43, 50.22}, who = "Lord Grayson Shadowbreaker"}, title = "Lord Grayson Shadowbreaker"},
	{{"complete", 7646, at = {1444, 54.39, 66.38}}, note = "An Azerothian Diamond comes from Thorium veins, a Pristine Black Diamond from the elites of the Western Plaguelands, both rarely: the Auction House is the usual source.", title = "Two diamonds"},
	{{"turnin", 7646, at = {1453, 48.43, 50.22}, who = "Lord Grayson Shadowbreaker"}, {"accept", 7647, at = {1453, 48.43, 50.22}, who = "Lord Grayson Shadowbreaker"}, title = "Lord Grayson Shadowbreaker"},
	{{"goto", 1422, 69.7, 73.2, "Scholomance"}, {"complete", 7647, at = {1422, 69.7, 73.2}}, {"turnin", 7647, at = {1422, 69.7, 73.2}, who = "Darkreaver's Fallen Charger"}, {"learn", 23214, name = "Summon Charger"}, note = "Scholomance lies under Caer Darrow, the island town in the south-east of the Western Plaguelands. Use the Divination Scryer in the heart of the Great Ossuary's basement, defeat the spirits it calls and then Death Knight Darkreaver, and give his Fallen Charger the Charger's Redeemed Soul and the Blessed Arcanite Barding. All are elite: bring a group. If the attempt fails, Lord Grayson gives you a new scryer through Again Into the Great Ossuary.", title = "The Great Ossuary"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"PALADIN"}, faction = "Alliance", id = "forever/collectibles/mounts/alliance/paladin-warhorse", levels = {40, 60}, map = 1453, title = "Paladin Warhorse", steps = {
	{{"level", 40}, {"accept", 4486, at = {1455, 23.13, 6.14}, who = "Brandur Ironhammer"}, note = "At 40 Brandur Ironhammer in the Mystic Ward sends you to Duthorian Rall in Stormwind's Cathedral of Light. Take the tram from Ironforge to Stormwind.", only = {races = {"Dwarf"}}, title = "The Tome of Nobility (Ironforge)"},
	{{"level", 40}, {"accept", 1661, at = {1453, 50.48, 47.49}, only = {races = {"Human"}}, who = "Duthorian Rall"}, {"turnin", 1661, at = {1453, 50.48, 47.49}, only = {races = {"Human"}}, who = "Duthorian Rall"}, {"turnin", 4486, at = {1453, 50.48, 47.49}, only = {races = {"Dwarf"}}, who = "Duthorian Rall"}, {"learn", 13819, name = "Summon Warhorse"}, note = "Duthorian Rall stands in the Cathedral of Light. Turning in the Tome of Nobility teaches Summon Warhorse; Paladins do not buy a mount.", title = "Summon Warhorse"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"WARLOCK"}, id = "forever/collectibles/mounts/neutral/warlock-dreadsteed", levels = {60, 60}, map = 1428, title = "Warlock Dreadsteed", steps = {
	{{"level", 60}, {"accept", 7562, at = {1453, 39.53, 84.53}, who = "Spackle Thornberry"}, note = "At 60 Spackle Thornberry in the Slaughtered Lamb sends you to Mor'zul Bloodbringer in the Burning Steppes.", only = {races = {"Human"}}, title = "Mor'zul Bloodbringer (Stormwind)"},
	{{"level", 60}, {"accept", 7562, at = {1455, 52.7, 6.08}, who = "Jubahl Corpseseeker"}, note = "At 60 Jubahl Corpseseeker in Ironforge sends you to Mor'zul Bloodbringer in the Burning Steppes.", only = {races = {"Gnome"}}, title = "Mor'zul Bloodbringer (Ironforge)"},
	{{"level", 60}, {"accept", 7562, at = {1454, 47.52, 46.72}, who = "Kurgul"}, note = "At 60 Kurgul in the Cleft of Shadow sends you to Mor'zul Bloodbringer in the Burning Steppes.", only = {races = {"Orc", "Troll"}}, title = "Mor'zul Bloodbringer (Orgrimmar)"},
	{{"level", 60}, {"accept", 7562, at = {1458, 85.7, 16.08}, who = "Martha Strain"}, note = "At 60 Martha Strain in the Magic Quarter sends you to Mor'zul Bloodbringer in the Burning Steppes.", only = {races = {"Scourge"}}, title = "Mor'zul Bloodbringer (Undercity)"},
	{{"turnin", 7562, at = {1428, 12.69, 31.64}, who = "Mor'zul Bloodbringer"}, {"accept", 7563, at = {1428, 12.69, 31.64}, who = "Mor'zul Bloodbringer"}, note = "Mor'zul Bloodbringer and his goblin Gorzeeki Wildeyes camp at the Altar of Storms, in the north-west of the Burning Steppes, west of Blackrock Mountain. The chain is long, costs gold at Gorzeeki's and ends in two dungeons.", title = "Mor'zul Bloodbringer"},
	{{"complete", 7563, at = {1452, 43.16, 39.43}}, note = "The owlbeasts of Winterspring drop the blood, about one in three: the Ragged and Raging Owlbeasts west of and around Everlook, the Crazed, Moontouched and Berserk ones in the east. While you hunt, start on the materials of the next step: the Auction House has them all.", title = "Raging Beast's Blood"},
	{{"turnin", 7563, at = {1428, 12.69, 31.64}, who = "Mor'zul Bloodbringer"}, {"accept", 7564, at = {1428, 12.69, 31.64}, who = "Mor'zul Bloodbringer"}, {"turnin", 7564, at = {1428, 12.44, 31.63}, who = "Gorzeeki Wildeyes"}, {"accept", 7626, at = {1428, 12.69, 31.64}, who = "Mor'zul Bloodbringer"}, {"accept", 7627, at = {1428, 12.69, 31.64}, who = "Mor'zul Bloodbringer"}, {"accept", 7628, at = {1428, 12.69, 31.64}, who = "Mor'zul Bloodbringer"}, {"accept", 7623, at = {1428, 12.44, 31.63}, who = "Gorzeeki Wildeyes"}, {"have", 18802, 2, at = {1428, 12.44, 31.63}, name = "Shadowy Potion"}, note = "Back to Mor'zul, then hand his Case of Blood to Gorzeeki Wildeyes beside him. Mor'zul then asks for three ritual pieces and Gorzeeki sends you to Felwood: buy two Shadowy Potions from Gorzeeki for that trip.", title = "Wildeyes"},
	{{"complete", 7626}, {"complete", 7627}, {"complete", 7628, at = {1428, 19.91, 45.36}}, note = "Gorzeeki wants 10 Elixirs of Shadow Power (Alchemy), 6 Large Brilliant Shards (Enchanting), 25 Dark Iron Ore (Mining, in Blackrock Depths and the Searing Gorge) and 35 Black Dragonscales (Skinning, black dragonkin of the Burning Steppes). Make or gather what your professions allow; buy the rest at the Auction House.", title = "The ritual pieces"},
	{{"turnin", 7626, at = {1428, 12.44, 31.63}, who = "Gorzeeki Wildeyes"}, {"turnin", 7627, at = {1428, 12.44, 31.63}, who = "Gorzeeki Wildeyes"}, {"turnin", 7628, at = {1428, 12.44, 31.63}, who = "Gorzeeki Wildeyes"}, {"accept", 7630, at = {1428, 12.44, 31.63}, who = "Gorzeeki Wildeyes"}, {"complete", 7630}, {"turnin", 7630, at = {1428, 12.44, 31.63}, who = "Gorzeeki Wildeyes"}, note = "Hand the three pieces to Gorzeeki. He then wants 3 Arcanite Bars: alchemists transmute them, everyone else buys them at the Auction House.", title = "Arcanite"},
	{{"turnin", 7623, at = {1448, 35.9, 44.4}, who = "Lord Banehollow"}, {"accept", 7624, at = {1448, 35.93, 44.42}, who = "Lord Banehollow"}, note = "Jaedenar is in western Felwood. Drink a Shadowy Potion before you go in: the Shadow Council cultists turn friendly for a while, the demons do not. Lord Banehollow waits deep inside Shadow Hold, the cave above Jaedenar, across a bridge in the great root chamber.", title = "Lord Banehollow"},
	{{"note", "Kill Ulathek", optional = true}, {"complete", 7624, at = {1448, 40.76, 48.42}}, {"turnin", 7624, at = {1448, 35.9, 44.4}, who = "Lord Banehollow"}, {"accept", 7625, at = {1448, 35.93, 44.42}, who = "Lord Banehollow"}, note = "Ulathek waits in a side chamber by a bridge on the way back up. Speak to him and he and his four guards attack; none are elite. Take his heart back to Lord Banehollow, drinking another potion if the first wore off.", title = "Ulathek the Traitor"},
	{{"have", 18687, 1, at = {1448, 36.18, 44.46}, name = "Xorothian Stardust"}, note = "Ur'dan, beside Lord Banehollow, sells the Xorothian Stardust; he only deals with you while a Shadowy Potion is active. Bring plenty of gold.", title = "Xorothian Stardust"},
	{{"have", 18687, 1, at = {1448, 36.18, 44.46}, name = "Xorothian Stardust"}, {"turnin", 7625, at = {1428, 12.44, 31.63}, who = "Gorzeeki Wildeyes"}, {"accept", 7629, at = {1428, 12.44, 31.63}, who = "Gorzeeki Wildeyes"}, note = "Back to Gorzeeki with the stardust. He gives you the Imp in a Jar for the Scholomance.", title = "Imp Delivery"},
	{{"complete", 7629, at = {1422, 69.7, 73.2}}, note = "The Scholomance lies under Caer Darrow, the island town in the south-east of the Western Plaguelands: you need its key or a rogue to open the door, and Rattlegore's Viewing Room Key to go deeper. Use the Imp in a Jar at the alchemy lab in Ras Frostwhisper's room; J'eevee makes the parchment. Bring a group.", title = "The Scholomance"},
	{{"turnin", 7629, at = {1428, 12.44, 31.63}, who = "Gorzeeki Wildeyes"}, {"accept", 7631, at = {1428, 12.69, 31.64}, who = "Mor'zul Bloodbringer"}, {"have", 18663, 1, at = {1428, 12.44, 31.63}, name = "J'eevee's Jar"}, {"have", 18629, 1, at = {1428, 12.44, 31.63}, name = "Black Lodestone"}, {"have", 18670, 1, at = {1428, 12.44, 31.63}, name = "Xorothian Glyphs"}, note = "Back to Gorzeeki, then Mor'zul hands you his instructions for the ritual. Buy J'eevee's Jar, the Black Lodestone and the Xorothian Glyphs from Gorzeeki, and carry ten or more Soul Shards.", title = "Dreadsteed of Xoroth"},
	{{"complete", 7631, at = {1444, 59.2, 45.1}}, {"turnin", 7631, at = {1444, 59.2, 45.1}, who = "Dreadsteed Spirit"}, {"learn", 23161, name = "Summon Dreadsteed"}, note = "Dire Maul stands in the ruins of central Feralas; the ritual circle is in its west wing, past Immol'thar, and the door needs the Crescent Key or a rogue. Use J'eevee's Jar to start; when the bell, the wheel or the candle fades, click it with the Black Lodestone (a Soul Shard each). When the demons stop coming, use the Xorothian Glyphs, defeat the Xorothian Dreadsteed and its dreadlord master, and speak to the Dreadsteed Spirit. Bring a group.", title = "The ritual in Dire Maul"},
} })

Pathwise.RegisterRoute({category = "Class", classes = {"WARLOCK"}, id = "forever/collectibles/mounts/neutral/warlock-felsteed", levels = {40, 60}, map = 1413, title = "Warlock Felsteed", steps = {
	{{"level", 40}, {"accept", 4488, at = {1453, 39.24, 84.96}, who = "Demisette Cloyce"}, note = "At 40 Demisette Cloyce in the Slaughtered Lamb, in the Mage Quarter, sends you to Strahad Farsan in Ratchet.", only = {races = {"Human"}}, title = "Summon Felsteed (Stormwind)"},
